-- P2: authoritative benchmark registry, verified provenance and aggregate version locks.
create table public.benchmark_registry_versions(
 id uuid primary key default extensions.gen_random_uuid(),metric_code text not null check(metric_code~'^[A-Z][A-Z0-9_.-]{1,119}$'),segment_key text not null check(segment_key~'^[A-Z][A-Z0-9_.-]{1,119}$'),version integer not null check(version>0),status text not null check(status in('ACTIVE','RETIRED')),minimum_value numeric(30,6) not null,maximum_value numeric(30,6) not null,unit_code text not null check(unit_code~'^[A-Z][A-Z0-9_.-]{1,39}$'),input_version_pattern text not null check(length(input_version_pattern)between 3 and 120),source_policy jsonb not null check(jsonb_typeof(source_policy)='object'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),effective_from timestamptz not null,effective_to timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),correlation_id uuid not null,unique(metric_code,segment_key,version),check(maximum_value>=minimum_value),check(effective_to is null or effective_to>effective_from)
);
create unique index benchmark_registry_one_active_uidx on public.benchmark_registry_versions(metric_code,segment_key)where status='ACTIVE';
create table private.benchmark_verified_sources(
 id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,metric_code text not null,segment_key text not null,period_start date not null,period_end date not null,input_version text not null,source_hash text not null check(source_hash~'^[0-9a-f]{64}$'),evidence_hash text not null check(evidence_hash~'^[0-9a-f]{64}$'),verification_method text not null check(verification_method in('SIGNED_IMPORT','AUDITED_CONNECTOR','ADMIN_ATTESTATION')),verified_by uuid not null references auth.users(id),verified_at timestamptz not null default clock_timestamp(),correlation_id uuid not null,unique(organization_id,metric_code,segment_key,period_start,period_end,input_version,source_hash),check(period_end>=period_start)
);
create function private.protect_benchmark_registry_history()returns trigger language plpgsql set search_path=pg_catalog as $$begin if tg_op='DELETE'or old.status<>'ACTIVE'or new.status<>'RETIRED'or new.effective_to is null or(to_jsonb(new)-array['status','effective_to'])is distinct from(to_jsonb(old)-array['status','effective_to'])then raise exception'BENCHMARK_REGISTRY_IMMUTABLE'using errcode='55000';end if;return new;end$$;
create trigger benchmark_registry_history_guard before update or delete on public.benchmark_registry_versions for each row execute function private.protect_benchmark_registry_history();
create trigger benchmark_verified_sources_immutable before update or delete on private.benchmark_verified_sources for each row execute function private.prevent_solution_benchmark_history_change();

create function public.publish_benchmark_registry_version(p_metric_code text,p_segment_key text,p_minimum_value numeric,p_maximum_value numeric,p_unit_code text,p_input_version_pattern text,p_source_policy jsonb,p_effective_from timestamptz,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();org uuid;h text;r jsonb;cached jsonb;vid uuid;ver integer;begin if a is null or auth.jwt()->>'aal'<>'aal2'or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],a)then raise exception'BENCHMARK_REGISTRY_MFA_REQUIRED'using errcode='42501';end if;select steward_organization_id into org from public.benchmark_privacy_policies where status='ACTIVE'limit 1;if org is null then raise exception'BENCHMARK_STEWARD_REQUIRED'using errcode='55000';end if;if p_metric_code!~'^[A-Z][A-Z0-9_.-]{1,119}$'or p_segment_key!~'^[A-Z][A-Z0-9_.-]{1,119}$'or p_maximum_value<p_minimum_value or p_unit_code!~'^[A-Z][A-Z0-9_.-]{1,39}$'or length(p_input_version_pattern)not between 3 and 120 or jsonb_typeof(p_source_policy)<>'object'or p_effective_from is null then raise exception'INVALID_BENCHMARK_REGISTRY'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('metric',p_metric_code,'segment',p_segment_key,'min',p_minimum_value,'max',p_maximum_value,'unit',p_unit_code,'input_pattern',p_input_version_pattern,'source_policy',p_source_policy,'effective_from',p_effective_from));cached:=private.begin_contract_command(org,'benchmark.registry.publish',p_idempotency_key,h,a);if cached is not null then return cached;end if;perform pg_advisory_xact_lock(hashtextextended('benchmark-registry:'||p_metric_code||':'||p_segment_key,0));if exists(select 1 from public.benchmark_registry_versions where metric_code=p_metric_code and segment_key=p_segment_key and status='ACTIVE'and effective_from>=p_effective_from)then raise exception'BENCHMARK_REGISTRY_EFFECTIVE_ORDER_INVALID'using errcode='22023';end if;select coalesce(max(version),0)+1 into ver from public.benchmark_registry_versions where metric_code=p_metric_code and segment_key=p_segment_key;update public.benchmark_registry_versions set status='RETIRED',effective_to=p_effective_from where metric_code=p_metric_code and segment_key=p_segment_key and status='ACTIVE';insert into public.benchmark_registry_versions(metric_code,segment_key,version,status,minimum_value,maximum_value,unit_code,input_version_pattern,source_policy,content_hash,effective_from,created_by,correlation_id)values(p_metric_code,p_segment_key,ver,'ACTIVE',p_minimum_value,p_maximum_value,p_unit_code,p_input_version_pattern,p_source_policy,h,p_effective_from,a,p_correlation_id)returning id into vid;r:=jsonb_build_object('outcome','BENCHMARK_REGISTRY_PUBLISHED','registry_version_id',vid,'version',ver,'content_hash',h);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(org,a,'USER','benchmark.registry.published','benchmark_registry_version',vid::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(org,'benchmark_registry',vid::text,'BenchmarkRegistryPublishedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(org,'benchmark.registry.publish',p_idempotency_key,r);return r;end$$;

create function public.verify_benchmark_source(p_organization_id uuid,p_metric_code text,p_segment_key text,p_period_start date,p_period_end date,p_input_version text,p_source_hash text,p_evidence_hash text,p_verification_method text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();h text;r jsonb;cached jsonb;sid uuid;begin if a is null or auth.jwt()->>'aal'<>'aal2'or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],a)then raise exception'BENCHMARK_SOURCE_VERIFY_DENIED'using errcode='42501';end if;if not exists(select 1 from public.organizations where id=p_organization_id)or p_source_hash!~'^[0-9a-f]{64}$'or p_evidence_hash!~'^[0-9a-f]{64}$'or p_verification_method not in('SIGNED_IMPORT','AUDITED_CONNECTOR','ADMIN_ATTESTATION')or not exists(select 1 from public.benchmark_registry_versions where metric_code=p_metric_code and segment_key=p_segment_key and status='ACTIVE'and p_input_version~input_version_pattern)then raise exception'INVALID_BENCHMARK_SOURCE_PROOF'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'metric',p_metric_code,'segment',p_segment_key,'period_start',p_period_start,'period_end',p_period_end,'input_version',p_input_version,'source_hash',p_source_hash,'evidence_hash',p_evidence_hash,'method',p_verification_method));cached:=private.begin_contract_command(p_organization_id,'benchmark.source.verify',p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into private.benchmark_verified_sources(organization_id,metric_code,segment_key,period_start,period_end,input_version,source_hash,evidence_hash,verification_method,verified_by,correlation_id)values(p_organization_id,p_metric_code,p_segment_key,p_period_start,p_period_end,p_input_version,p_source_hash,p_evidence_hash,p_verification_method,a,p_correlation_id)returning id into sid;r:=jsonb_build_object('outcome','BENCHMARK_SOURCE_VERIFIED','source_verification_id',sid);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','benchmark.source.verified','benchmark_source',sid::text,p_correlation_id,jsonb_build_object('metric_code',p_metric_code,'segment_key',p_segment_key,'evidence_hash',p_evidence_hash,'verification_method',p_verification_method),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'benchmark_source',sid::text,'BenchmarkSourceVerifiedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'benchmark.source.verify',p_idempotency_key,r);return r;end$$;

create or replace function public.submit_benchmark_contribution(p_organization_id uuid,p_metric_code text,p_segment_key text,p_period_start date,p_period_end date,p_value_exact numeric,p_input_version text,p_source_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();h text;r jsonb;cached jsonb;cid uuid;registry public.benchmark_registry_versions%rowtype;begin if a is null or not private.has_org_role(p_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)then raise exception'BENCHMARK_CONTRIBUTION_DENIED'using errcode='42501';end if;if p_metric_code!~'^[A-Z][A-Z0-9_.-]{1,119}$'or p_segment_key!~'^[A-Z][A-Z0-9_.-]{1,119}$'or p_period_start is null or p_period_end<p_period_start or length(btrim(coalesce(p_input_version,'')))not between 1 and 120 or p_source_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_BENCHMARK_CONTRIBUTION'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'metric',p_metric_code,'segment',p_segment_key,'period_start',p_period_start,'period_end',p_period_end,'value',p_value_exact,'input_version',p_input_version,'source_hash',p_source_hash));cached:=private.begin_contract_command(p_organization_id,'benchmark.contribution.submit',p_idempotency_key,h,a);if cached is not null then return cached;end if;perform pg_advisory_xact_lock(hashtextextended('benchmark-cell:'||p_metric_code||':'||p_segment_key||':'||p_period_start::text||':'||p_period_end::text,0));if exists(select 1 from public.benchmark_publications where metric_code=p_metric_code and segment_key=p_segment_key and period_start=p_period_start and period_end=p_period_end)then raise exception'BENCHMARK_CELL_SEALED'using errcode='55000';end if;select*into registry from public.benchmark_registry_versions where metric_code=p_metric_code and segment_key=p_segment_key and status='ACTIVE'and effective_from<=clock_timestamp()and(effective_to is null or effective_to>clock_timestamp());if not found then raise exception'BENCHMARK_METRIC_SEGMENT_NOT_REGISTERED'using errcode='22023';end if;if p_value_exact<registry.minimum_value or p_value_exact>registry.maximum_value then raise exception'BENCHMARK_VALUE_OUT_OF_BOUNDS'using errcode='22003';end if;if p_input_version!~registry.input_version_pattern or not exists(select 1 from private.benchmark_verified_sources s where s.organization_id=p_organization_id and s.metric_code=p_metric_code and s.segment_key=p_segment_key and s.period_start=p_period_start and s.period_end=p_period_end and s.input_version=p_input_version and s.source_hash=p_source_hash)then raise exception'BENCHMARK_SOURCE_NOT_VERIFIED'using errcode='22023';end if;insert into private.benchmark_contributions(organization_id,metric_code,segment_key,period_start,period_end,value_exact,input_version,source_hash,submitted_by,correlation_id)values(p_organization_id,p_metric_code,p_segment_key,p_period_start,p_period_end,p_value_exact,p_input_version,p_source_hash,a,p_correlation_id)returning id into cid;r:=jsonb_build_object('outcome','BENCHMARK_CONTRIBUTION_ACCEPTED','contribution_id',cid,'registry_version_id',registry.id,'metric_code',p_metric_code,'period_end',p_period_end);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','benchmark.contribution.submitted','benchmark_contribution',cid::text,p_correlation_id,jsonb_build_object('registry_version_id',registry.id,'metric_code',p_metric_code,'segment_key',p_segment_key,'source_hash',p_source_hash),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'benchmark_contribution',cid::text,'BenchmarkContributionAcceptedV2',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'benchmark.contribution.submit',p_idempotency_key,r);return r;end$$;

create function private.enforce_solution_bundle_version_sequence()returns trigger language plpgsql set search_path=pg_catalog as $$declare expected integer;begin perform pg_advisory_xact_lock(hashtextextended('solution-bundle:'||new.organization_id::text||':'||new.bundle_key,0));select coalesce(max(version),0)+1 into expected from public.solution_bundle_versions where organization_id=new.organization_id and bundle_key=new.bundle_key;if new.version<>expected then raise exception'INVALID_BUNDLE_VERSION_SEQUENCE'using errcode='40001';end if;return new;end$$;
create trigger solution_bundle_version_sequence before insert on public.solution_bundle_versions for each row execute function private.enforce_solution_bundle_version_sequence();
create function private.enforce_benchmark_policy_version_sequence()returns trigger language plpgsql set search_path=pg_catalog as $$declare expected integer;begin perform pg_advisory_xact_lock(hashtextextended('benchmark-privacy-policy',0));select coalesce(max(version),0)+1 into expected from public.benchmark_privacy_policies;if new.version<>expected then raise exception'INVALID_BENCHMARK_POLICY_VERSION_SEQUENCE'using errcode='40001';end if;return new;end$$;
create trigger benchmark_policy_version_sequence before insert on public.benchmark_privacy_policies for each row execute function private.enforce_benchmark_policy_version_sequence();

alter table public.benchmark_registry_versions enable row level security;alter table private.benchmark_verified_sources enable row level security;
create policy benchmark_registry_read on public.benchmark_registry_versions for select to authenticated using(true);
revoke all on public.benchmark_registry_versions from public,anon,authenticated,service_role;grant select on public.benchmark_registry_versions to authenticated;revoke all on private.benchmark_verified_sources from public,anon,authenticated,service_role;
revoke all on function private.protect_benchmark_registry_history(),private.enforce_solution_bundle_version_sequence(),private.enforce_benchmark_policy_version_sequence(),public.publish_benchmark_registry_version(text,text,numeric,numeric,text,text,jsonb,timestamptz,text,uuid),public.verify_benchmark_source(uuid,text,text,date,date,text,text,text,text,text,uuid),public.submit_benchmark_contribution(uuid,text,text,date,date,numeric,text,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.publish_benchmark_registry_version(text,text,numeric,numeric,text,text,jsonb,timestamptz,text,uuid),public.verify_benchmark_source(uuid,text,text,date,date,text,text,text,text,text,uuid),public.submit_benchmark_contribution(uuid,text,text,date,date,numeric,text,text,text,uuid)to authenticated;
create index benchmark_registry_lookup_idx on public.benchmark_registry_versions(metric_code,segment_key,status,effective_from desc);create index benchmark_verified_source_lookup_idx on private.benchmark_verified_sources(organization_id,metric_code,segment_key,period_start,period_end,input_version,source_hash);
notify pgrst,'reload schema';
